14	/// The Home/Chat screen's own live conversation — streaming, retry, lazy
15	/// session creation, composer gating (contracts/chat-bloc.md). Depends only
16	/// on `ChatRepository` + `ConnectivityChecker` — never `ChatSessionsBloc`
17	/// nor `SessionBloc` (research.md R7).
18	class ChatBloc extends Bloc<ChatEvent, ChatState> {
19	  ChatBloc({
20	    required ChatRepository chatRepository,
21	    required ConnectivityChecker connectivityChecker,
22	  }) : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
23	       _connectivityChecker = connectivityChecker, // ignore: prefer_initializing_formals
24	       super(const ChatLoading()) {
25	    on<ChatStarted>(_onStarted);
26	    on<ConversationSelected>(_onConversationSelected);
27	    on<NewConversationRequested>(_onNewConversationRequested);
28	    on<MessageSubmitted>(_onMessageSubmitted);
29	    on<MessageRetryRequested>(_onMessageRetryRequested);
30	    on<ChatConnectivityChanged>(_onConnectivityChanged);
31	    _connectivitySubscription = connectivityChecker.onConnectivityChanged.listen(
32	      (isOnline) => add(ChatConnectivityChanged(isOnline)),
33	    );
34	  }
35	
36	  final ChatRepository _chatRepository;
37	  final ConnectivityChecker _connectivityChecker;
38	  late final StreamSubscription<bool> _connectivitySubscription;
39	  final _reauthController = StreamController<void>.broadcast();
40	
41	  /// Guards against a resolved/superseded turn's late emit (defensive,
42	  /// research.md R9) — bumped on every new turn and on every conversation
43	  /// switch/new-conversation request.
44	  int _turnGeneration = 0;
45	
46	  /// A one-shot side effect, not a state (research.md R3/R7) —
47	  /// `HomeChatShellPage` listens to this to raise the "Sessão expirada"
48	  /// overlay.
49	  Stream<void> get reauthRequired => _reauthController.stream;
50	
51	  Future<void> _onStarted(ChatStarted event, Emitter<ChatState> emit) async {
52	    final isOnline = await _connectivityChecker.hasConnection();
53	    final lastId = await _chatRepository.lastActiveSessionId;
54	    if (lastId == null) {
55	      emit(
56	        ChatReady(
57	          sessionId: null,
58	          messages: const [],
59	          isOffline: !isOnline,
60	          awaitingResponse: false,
61	        ),
62	      );
63	      return;
64	    }
65	    await _loadSession(lastId, emit, isOffline: !isOnline);
66	  }
67	
68	  Future<void> _onConversationSelected(
69	    ConversationSelected event,
70	    Emitter<ChatState> emit,
71	  ) async {
72	    _turnGeneration++;
73	    final isOnline = await _connectivityChecker.hasConnection();
74	    await _loadSession(event.sessionId, emit, isOffline: !isOnline);
75	  }
76	
77	  Future<void> _onNewConversationRequested(
78	    NewConversationRequested event,
79	    Emitter<ChatState> emit,
80	  ) async {
81	    _turnGeneration++;
82	    final current = state;
83	    final isOffline = current is ChatReady ? current.isOffline : false;
84	    await _chatRepository.setLastActiveSessionId(null);
85	    emit(
86	      ChatReady(
87	        sessionId: null,
88	        messages: const [],
89	        isOffline: isOffline,
90	        awaitingResponse: false,
91	      ),
92	    );
93	  }
94	
95	  void _onConnectivityChanged(
96	    ChatConnectivityChanged event,
97	    Emitter<ChatState> emit,
98	  ) {
99	    final current = state;
100	    if (current is! ChatReady) return;
101	    emit(current.copyWith(isOffline: !event.isOnline));
102	  }
103	
104	  /// The shared fetch-with-cache-fallback path (Clarification 3).
105	  Future<void> _loadSession(
106	    String sessionId,
107	    Emitter<ChatState> emit, {
108	    required bool isOffline,
109	  }) async {
110	    final result = await _chatRepository.listMessages(sessionId);
111	    await result.match(
112	      (failure) async {
113	        if (failure is AuthExpiredFailure) _reauthController.add(null);
114	        final cached = _chatRepository.cachedMessages(sessionId);
115	        if (cached == null) {
116	          // Never opened while online — the "standard no-connection state"
117	          // instead of any content (Edge Cases).
118	          emit(
119	            ChatReady(
120	              sessionId: sessionId,
121	              messages: const [],
122	              isOffline: isOffline,
123	              awaitingResponse: false,
124	              loadFailure: failure,
125	            ),
126	          );
127	        } else {
128	          emit(
129	            ChatReady(
130	              sessionId: sessionId,
131	              messages: cached,
132	              isOffline: isOffline,
133	              awaitingResponse: false,
134	            ),
135	          );
136	        }
137	      },
138	      (messages) async {
139	        await _chatRepository.setLastActiveSessionId(sessionId);
140	        emit(
141	          ChatReady(
142	            sessionId: sessionId,
143	            messages: messages,
144	            isOffline: isOffline,
145	            awaitingResponse: false,
146	          ),
147	        );
148	      },
149	    );
150	  }
151	
152	  Future<void> _onMessageSubmitted(
153	    MessageSubmitted event,
154	    Emitter<ChatState> emit,
155	  ) async {
156	    final current = state;
157	    if (current is! ChatReady || !current.canSend) return;
158	
159	    if (!await _connectivityChecker.hasConnection()) {
160	      // FR-012 — blocked client-side, never attempted. The composer's own
161	      // isOffline flag (R8's live stream) reflects this on its own shortly.
162	      return;
163	    }
164	
165	    final generation = ++_turnGeneration;
166	    final now = DateTime.now();
167	    final optimisticUser = ChatMessage(
168	      id: 'local-${now.microsecondsSinceEpoch}',
169	      sessionId: current.sessionId ?? '',
170	      role: ChatRole.user,
171	      content: event.text,
172	      seq: current.messages.length,
173	      status: ChatMessageStatus.complete,
174	      retryCount: 0,
175	      createdAt: now,
176	    );
177	    final optimisticAssistant = ChatMessage(
178	      id: 'local-${now.microsecondsSinceEpoch}-response',
179	      sessionId: current.sessionId ?? '',
180	      role: ChatRole.assistant,
181	      content: '',
182	      seq: current.messages.length + 1,
183	      status: ChatMessageStatus.streaming,
184	      retryCount: 0,
185	      createdAt: now,
186	    );
187	    emit(
188	      current.copyWith(
189	        messages: [...current.messages, optimisticUser, optimisticAssistant],
190	        awaitingResponse: true,
191	      ),
192	    );
193	
194	    String sessionId;
195	    if (current.sessionId == null) {
196	      final created = await _chatRepository.createSession(
197	        title: ChatTitleDeriver.derive(event.text),
198	      );
199	      if (generation != _turnGeneration) return;
200	      final maybeId = created.match((_) => null, (s) => s.id);
201	      if (maybeId == null) {
202	        final failure = created.getLeft().toNullable()!;
203	        _failTurn(emit, optimisticAssistant.id, failure);
204	        return;
205	      }
206	      sessionId = maybeId;
207	      await _chatRepository.setLastActiveSessionId(sessionId);
208	    } else {
209	      sessionId = current.sessionId!;
210	    }
211	
212	    final stream = _chatRepository.sendMessage(
213	      sessionId: sessionId,
214	      content: event.text,
215	    );
216	    await _consumeTurn(
217	      stream,
218	      emit,
219	      generation: generation,
220	      optimisticUserId: optimisticUser.id,
221	      optimisticAssistantId: optimisticAssistant.id,
222	    );
223	  }
224	
225	  Future<void> _onMessageRetryRequested(
226	    MessageRetryRequested event,
227	    Emitter<ChatState> emit,
228	  ) async {
229	    final current = state;
230	    if (current is! ChatReady || current.awaitingResponse) {
231	      return;
232	    }
233	    final index = current.messages.indexWhere(
234	      (m) =>
235	          m.role == ChatRole.assistant &&
236	          m.status == ChatMessageStatus.failed &&
237	          _userMessageIdFor(current.messages, m) == event.userMessageId,
238	    );
239	    if (index == -1) return;
240	    if (!await _connectivityChecker.hasConnection()) return; // FR-012
241	
242	    final userMessage = current.messages[index - 1];
243	    if (userMessage.isOptimistic) {
244	      // The turn's very first `createSession` call failed (FR-006) — there
245	      // is no persisted session/message yet for `retryMessage` to target, so
246	      // re-run the same lazy-creation path `_onMessageSubmitted` takes.
247	      await _retryLazySessionCreation(current, index, userMessage, emit);
248	      return;
249	    }
250	    if (current.sessionId == null) return;
251	
252	    final generation = ++_turnGeneration;
253	    final now = DateTime.now();
254	    final placeholder = ChatMessage(
255	      id: 'local-${now.microsecondsSinceEpoch}-retry',
256	      sessionId: current.sessionId!,
257	      role: ChatRole.assistant,
258	      content: '',
259	      seq: current.messages[index].seq,
260	      status: ChatMessageStatus.streaming,
261	      retryCount: current.messages[index].retryCount + 1,
262	      createdAt: now,
263	    );
264	    final updatedMessages = [...current.messages];
265	    updatedMessages[index] = placeholder;
266	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
267	
268	    final stream = _chatRepository.retryMessage(
269	      sessionId: current.sessionId!,
270	      userMessageId: event.userMessageId,
271	    );
272	    await _consumeTurn(
273	      stream,
274	      emit,
275	      generation: generation,
276	      optimisticUserId: null,
277	      optimisticAssistantId: placeholder.id,
278	    );
279	  }
280	
281	  /// Retries a turn whose lazy `createSession` call (FR-010) itself failed
282	  /// before any session ever existed — reuses `createSession` +
283	  /// `sendMessage` with the original user message's own content, exactly as
284	  /// `_onMessageSubmitted` does for a brand-new conversation.
285	  Future<void> _retryLazySessionCreation(
286	    ChatReady current,
287	    int index,
288	    ChatMessage userMessage,
289	    Emitter<ChatState> emit,
290	  ) async {
291	    final generation = ++_turnGeneration;
292	    final now = DateTime.now();
293	    final placeholder = ChatMessage(
294	      id: 'local-${now.microsecondsSinceEpoch}-retry',
295	      sessionId: userMessage.sessionId,
296	      role: ChatRole.assistant,
297	      content: '',
298	      seq: current.messages[index].seq,
299	      status: ChatMessageStatus.streaming,
300	      retryCount: current.messages[index].retryCount + 1,
301	      createdAt: now,
302	    );
303	    final updatedMessages = [...current.messages];
304	    updatedMessages[index] = placeholder;
305	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
306	
307	    final created = await _chatRepository.createSession(
308	      title: ChatTitleDeriver.derive(userMessage.content),
309	    );
310	    if (generation != _turnGeneration) return;
311	    final maybeId = created.match((_) => null, (s) => s.id);
312	    if (maybeId == null) {
313	      final failure = created.getLeft().toNullable()!;
314	      _failTurn(emit, placeholder.id, failure);
315	      return;
316	    }
317	    await _chatRepository.setLastActiveSessionId(maybeId);
318	
319	    final latest = state;
320	    if (latest is! ChatReady || generation != _turnGeneration) return;
321	    emit(latest.copyWith(sessionId: maybeId));
322	
323	    final stream = _chatRepository.sendMessage(
324	      sessionId: maybeId,
325	      content: userMessage.content,
326	    );
327	    await _consumeTurn(
328	      stream,
329	      emit,
330	      generation: generation,
331	      optimisticUserId: userMessage.id,
332	      optimisticAssistantId: placeholder.id,
333	    );
334	  }
335	
336	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
337	  /// and a retry.
338	  Future<void> _consumeTurn(
339	    Stream<Either<Failure, ChatStreamEvent>> stream,
340	    Emitter<ChatState> emit, {
341	    required int generation,
342	    required String? optimisticUserId,
343	    required String optimisticAssistantId,
344	  }) async {
345	    var assistantId = optimisticAssistantId;
346	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
347	      stream,
348	      onData: (result) {
349	        final latest = state;
350	        if (generation != _turnGeneration || latest is! ChatReady) {
351	          return latest;
352	        }
353	        return result.match((failure) {
354	          if (failure is AuthExpiredFailure) _reauthController.add(null);
355	          return _applyFailure(latest, assistantId, failure);
356	        }, (event) => switch (event) {
357	          MessageCreated() => () {
358	            assistantId = event.assistantMessageId;
359	            return _reconcileIds(
360	              latest,
361	              optimisticUserId,
362	              event.userMessageId,
363	              optimisticAssistantId,
364	              event.assistantMessageId,
365	            );
366	          }(),
367	          ContextReceived() => latest,
368	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
369	          StreamDone(
370	            assistantMessageId: final id,
371	            content: final c,
372	            createdAt: final t,
373	          ) =>
374	            _completeMessage(latest, id, c, t).copyWith(awaitingResponse: false),
375	        });
376	      },
377	    );
378	  }
379	
380	  void _failTurn(
381	    Emitter<ChatState> emit,
382	    String assistantId,
383	    Failure failure,
384	  ) {
385	    final latest = state;
386	    if (latest is! ChatReady) return;
387	    emit(_applyFailure(latest, assistantId, failure));
388	  }
389	
390	  /// `null` for a retry's `userMessageId` — a retry never targets an
391	  /// optimistic question, only an already-persisted one.
392	  ChatReady _reconcileIds(
393	    ChatReady current,
394	    String? optimisticUserId,
395	    String realUserId,
396	    String optimisticAssistantId,
397	    String realAssistantId,
398	  ) {
399	    final updated = [
400	      for (final m in current.messages)
401	        if (optimisticUserId != null && m.id == optimisticUserId)
402	          _withId(m, realUserId)
403	        else if (m.id == optimisticAssistantId)
404	          _withId(m, realAssistantId)
405	        else
406	          m,
407	    ];
408	    return current.copyWith(messages: updated);
409	  }
410	
411	  ChatMessage _withId(ChatMessage message, String id) => ChatMessage(
412	    id: id,
413	    sessionId: message.sessionId,
414	    role: message.role,
415	    content: message.content,
416	    seq: message.seq,
417	    status: message.status,
418	    retryCount: message.retryCount,
419	    createdAt: message.createdAt,
420	  );
421	
422	  ChatReady _appendToken(ChatReady current, String assistantId, String delta) {
423	    final updated = [
424	      for (final m in current.messages)
425	        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
426	    ];
427	    return current.copyWith(messages: updated);
428	  }
429	
430	  ChatReady _completeMessage(
431	    ChatReady current,
432	    String assistantId,
433	    String content,
434	    DateTime createdAt,
435	  ) {
436	    final updated = [
437	      for (final m in current.messages)
438	        if (m.id == assistantId)
439	          ChatMessage(
440	            id: m.id,
441	            sessionId: m.sessionId,
442	            role: m.role,
443	            content: content,
444	            seq: m.seq,
445	            status: ChatMessageStatus.complete,
446	            retryCount: m.retryCount,
447	            createdAt: createdAt,
448	          )
449	        else
450	          m,
451	    ];
452	    return current.copyWith(messages: updated);
453	  }
454	
455	  /// Keeps whatever partial `content` had already accumulated — never
456	  /// removed, hidden, or blanked (FR-005).
457	  ChatReady _applyFailure(
458	    ChatReady current,
459	    String assistantId,
460	    Failure failure,
461	  ) {
462	    final updated = [
463	      for (final m in current.messages)
464	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.failed) else m,
465	    ];
466	    return current.copyWith(messages: updated, awaitingResponse: false);
467	  }
468	
469	  ChatMessage _withContent(ChatMessage message, String content) => ChatMessage(
470	    id: message.id,
471	    sessionId: message.sessionId,
472	    role: message.role,
473	    content: content,
474	    seq: message.seq,
475	    status: message.status,
476	    retryCount: message.retryCount,
477	    createdAt: message.createdAt,
478	  );
479	
480	  ChatMessage _withStatus(ChatMessage message, ChatMessageStatus status) =>
481	      ChatMessage(
482	        id: message.id,
483	        sessionId: message.sessionId,
484	        role: message.role,
485	        content: message.content,
486	        seq: message.seq,
487	        status: status,
488	        retryCount: message.retryCount,
489	        createdAt: message.createdAt,
490	      );
491	
492	  /// Position-matching (research.md R10) — the id of the user message
493	  /// immediately preceding [message] in [messages], or `null` if it isn't
494	  /// immediately preceded by one.
495	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
496	    final index = messages.indexWhere((m) => m.id == message.id);
497	    if (index <= 0) return null;
498	    final preceding = messages[index - 1];
499	    return preceding.role == ChatRole.user ? preceding.id : null;
500	  }
501	
502	  @override
503	  Future<void> close() {
504	    unawaited(_connectivitySubscription.cancel());
505	    unawaited(_reauthController.close());
506	    return super.close();
507	  }
508	}
