class _SessionTile extends StatelessWidget {
  const _SessionTile({required this.session});

  final ChatSession session;

  @override
  Widget build(BuildContext context) {
    final timestamp = (session.lastUserMessageAt ?? session.updatedAt).toLocal();
    final timestampLabel =
        '${timestamp.day.toString().padLeft(2, '0')}/${timestamp.month.toString().padLeft(2, '0')} '
        '${timestamp.hour.toString().padLeft(2, '0')}:${timestamp.minute.toString().padLeft(2, '0')}';

    return ListTile(
      title: Text(session.title, style: DesignTokens.textBodyLg, maxLines: 1, overflow: TextOverflow.ellipsis),
      subtitle: Text(
        timestampLabel,
        style: DesignTokens.textLabelMd.copyWith(color: DesignTokens.colorTextSecondary),
      ),
      onTap: () {
        Navigator.of(context).pop();
        context.read<ChatBloc>().add(ConversationSelected(session.id));
      },
    );
  }
}

