import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/widgets/open_insertion_modal.dart';
import 'package:cerne/features/chat/presentation/bloc/chat_bloc.dart';
import 'package:cerne/features/chat/presentation/bloc/chat_event.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// Replaces `_ComposerBar`. Owns its own [TextEditingController] — never
/// part of `ChatState` (research.md's "composer text is local" choice), so
/// nothing typed is ever lost on any failure.
class ChatComposer extends StatefulWidget {
  const ChatComposer({required this.canSend, super.key});

  final bool canSend;

  @override
  State<ChatComposer> createState() => _ChatComposerState();
}

class _ChatComposerState extends State<ChatComposer> {
  final _controller = TextEditingController();

  void _handleSend() {
    final text = _controller.text.trim();
    if (text.isEmpty || !widget.canSend) return;
    context.read<ChatBloc>().add(MessageSubmitted(text));
    _controller.clear();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        border: Border(top: BorderSide(color: DesignTokens.colorBorder)),
      ),
      child: Row(
        children: [
          IconButton(
            onPressed: () => openInsertionModal(context),
            icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
          ),
          Expanded(
            child: ValueListenableBuilder<TextEditingValue>(
              valueListenable: _controller,
              builder: (context, value, _) {
                return TextField(
                  controller: _controller,
                  enabled: widget.canSend,
                  maxLength: 8000,
                  decoration: const InputDecoration(
                    hintText: 'Escreva uma mensagem...',
                    counterText: '',
                  ),
                  onSubmitted: (_) => _handleSend(),
                );
              },
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          ValueListenableBuilder<TextEditingValue>(
            valueListenable: _controller,
            builder: (context, value, _) {
              final canTapSend = widget.canSend && value.text.trim().isNotEmpty;
              return IconButton(
                onPressed: canTapSend ? _handleSend : null,
                icon: Icon(
                  Icons.send,
                  color: canTapSend
                      ? DesignTokens.colorPrimary
                      : DesignTokens.colorTextSecondary,
                ),
              );
            },
          ),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/chat/domain/entities/chat_message.dart';
import 'package:flutter/material.dart';

/// One widget, branching on [ChatMessage.role]/[ChatMessage.status]
/// (data-model.md). `streaming` → a pulsing-cursor indicator, not tappable;
/// `complete` → final text + timestamp, no indicator; `failed` → "Falha ao
/// gerar resposta — toque para tentar novamente" in place of the timestamp,
/// tappable only in this state (FR-004/FR-006).
class ChatMessageBubble extends StatelessWidget {
  const ChatMessageBubble({required this.message, this.onRetryTap, super.key});

  final ChatMessage message;
  final VoidCallback? onRetryTap;

  bool get _isUser => message.role == ChatRole.user;

  @override
  Widget build(BuildContext context) {
    final isFailed = message.status == ChatMessageStatus.failed;

    return Align(
      alignment: _isUser ? Alignment.centerRight : Alignment.centerLeft,
      child: GestureDetector(
        onTap: isFailed ? onRetryTap : null,
        child: Container(
          margin: const EdgeInsets.symmetric(
            horizontal: DesignTokens.spacingMd,
            vertical: DesignTokens.spacingXs,
          ),
          padding: const EdgeInsets.all(DesignTokens.spacingMd),
          constraints: BoxConstraints(
            maxWidth: MediaQuery.of(context).size.width * 0.8,
          ),
          decoration: BoxDecoration(
            color: _isUser
                ? DesignTokens.colorChatBubbleUser
                : DesignTokens.colorSurfaceElevated,
            borderRadius: BorderRadius.only(
              topLeft: const Radius.circular(DesignTokens.radiusMd),
              topRight: const Radius.circular(DesignTokens.radiusMd),
              bottomLeft: Radius.circular(_isUser ? DesignTokens.radiusMd : 0),
              bottomRight: Radius.circular(_isUser ? 0 : DesignTokens.radiusMd),
            ),
            boxShadow: _isUser ? null : DesignTokens.elevation1,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(message.content, style: DesignTokens.textBodyMd),
              const SizedBox(height: DesignTokens.spacingXs),
              _StatusLine(message: message),
            ],
          ),
        ),
      ),
    );
  }
}

class _StatusLine extends StatelessWidget {
  const _StatusLine({required this.message});

  final ChatMessage message;

  @override
  Widget build(BuildContext context) {
    switch (message.status) {
      case ChatMessageStatus.streaming:
        return Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            SizedBox(
              width: DesignTokens.sizeLoadingDot,
              height: DesignTokens.sizeLoadingDot,
              child: CircularProgressIndicator(
                strokeWidth: DesignTokens.strokeWidthLoadingIndicator,
                color: DesignTokens.colorTextPrimary,
              ),
            ),
          ],
        );
      case ChatMessageStatus.complete:
        return Text(
          TimeOfDay.fromDateTime(message.createdAt).format(context),
          style: DesignTokens.textLabelMd.copyWith(
            color: DesignTokens.colorTextSecondary,
          ),
        );
      case ChatMessageStatus.failed:
        return Text(
          'Falha ao gerar resposta — toque para tentar novamente',
          style: DesignTokens.textLabelMd.copyWith(color: DesignTokens.colorError),
        );
    }
  }
}

